#include "Vitch_parser.h" // class generated by Verilator
#include <verilated.h> // runtime thing for Verilator
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include "contracts.hpp"
#include "itch_messages.hpp"

static constexpr int RESET_CYCLES = 5; // constexpr is C++ for eval this at compile time, not run time
static constexpr int TDATA_WORDS = 15; // 480b = 15 words * 32 bits

static int failures = 0;

static void tick(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    //

    dut->clk = 0;
    dut->eval(); // recompute w clk LO (nothing captures)
    dut->clk = 1;
    dut->eval(); // rising edge (clk 0->1) so eval sees t hat and fires always_ff @(posedge) blocks
    
    //
    ENSURES(dut->clk == 1);
}

static void reset(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    //
    
    dut->rst_n = 0;
    dut->s_axis_tvalid = 0;
    dut->s_axis_tdata = 0;
    dut->m_axis_tready = 1;

    for (int i = 0; i < RESET_CYCLES; i++){
        tick(dut);
    }

    dut->rst_n = 1;
    tick(dut);

    //
    ENSURES(dut->rst_n == 1);
    ENSURES(dut->m_axis_tvalid == 0);
    ENSURES(dut->s_axis_tready == 1);
}


/*
word 14:
rsvd3 (8b) - 479:472
trading_state (8b) - 471:464
market_code (8b) - 463:456
op_halt_action (8b) - 455:448

word 13,12:
new_order_ref (64b) - 447:384

word11:
rsvd0 (27b) - 383:357
is_buy (1b) - 356
msg_type (4b) - 355:352 

word10:
rsvd1 (16b) - 351:336
stock_locate - 335:320

word 9,8:
rsvd2 (16b) - 319:304
timestamp (48b) - 303:256

word 7,6:
order_ref (64b) - 255:192

word 5:
shares (32b) - 191:160

word 4,3:
stock (64b) - 159:96

word 2:
price (32b) - 95:64

word 1:
match_num (64b) - 63:0
*/

// extract from padding
static inline uint8_t get_trading_state(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (uint8_t)((dut->m_axis_tdata[14] >> 16) & 0xFF);
}
static inline uint8_t get_market_code(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (uint8_t)((dut->m_axis_tdata[14] >> 8) & 0xFF);
}
static inline uint8_t get_op_halt_action(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (uint8_t)(dut->m_axis_tdata[14] & 0xFF);
}
static inline uint64_t get_new_order_ref(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return ((uint64_t)dut->m_axis_tdata[13] << 32) | dut->m_axis_tdata[12];
}
static inline uint64_t get_match_num(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return ((uint64_t)dut->m_axis_tdata[1] << 32) | dut->m_axis_tdata[0];
}
static inline uint32_t get_price(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return dut->m_axis_tdata[2];
}
static inline uint64_t get_stock(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return ((uint64_t)dut->m_axis_tdata[4] << 32) | dut->m_axis_tdata[3];
}
static inline uint32_t get_shares(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return dut->m_axis_tdata[5];
}
static inline uint64_t get_order_ref(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return ((uint64_t)dut->m_axis_tdata[7] << 32) | dut->m_axis_tdata[6];
}
static inline uint64_t get_timestamp(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return ((uint64_t)dut->m_axis_tdata[9] << 32) | dut->m_axis_tdata[8];
}
static inline uint16_t get_locate(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (uint16_t)(dut->m_axis_tdata[10] & 0xFFFF);
}
static inline uint8_t get_msg_type(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (uint8_t)(dut->m_axis_tdata[11] & 0xF);
}
static inline bool get_is_buy(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->m_axis_tvalid);
    //

    return (dut->m_axis_tdata[11] >> 4) & 1;
}

static int push_byte(
    Vitch_parser* dut, 
    uint8_t b, 
    bool *msg_out = nullptr, 
    int max_wait = 100
){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->rst_n ==1);
    REQUIRES(max_wait > 0);
    //
    
    dut->s_axis_tdata = b;
    dut->s_axis_tvalid = 1;

    if (msg_out != nullptr){
        *msg_out = false;
    }

    for (int wait = 0; wait < max_wait; wait++){
        dut->eval();
        bool accepted = dut->s_axis_tready;
        
        if (msg_out!=nullptr && dut->m_axis_tvalid && dut->m_axis_tready){
            *msg_out = true;
        }
        
        tick(dut);
        if (accepted){
            ENSURES(wait >= 0);
            return wait;
        }
    }

    std::printf("FAILED: byte stalled for >%d cycles\n", max_wait);
    failures++;
    return -1;

}

static void feed_byte(
    Vitch_parser* dut,
    uint8_t b,
    bool *got_msg,
    uint8_t *out_type,
    uint64_t *out_ref,
    uint32_t *out_shares,
    int max_wait = 100    
){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->rst_n == 1);
    REQUIRES(got_msg != nullptr);
    //

    dut->s_axis_tdata = b;
    dut->s_axis_tvalid = 1;
    *got_msg = false;

    for (int wait = 0; wait < max_wait; wait++){
        dut->eval();
        bool accepted = dut->s_axis_tready;

        if (dut->m_axis_tvalid && dut->m_axis_tready && *got_msg==false){
            *got_msg = true;
            *out_type = get_msg_type(dut);
            *out_ref = get_order_ref(dut);
            *out_shares = get_shares(dut);
        }

        tick(dut);
        if (accepted){
            return;
        }
    }
    std::printf("FAILED: byte stalled for >%d cycles\n", max_wait);
    failures++;
}

static void send_msg(Vitch_parser* dut, const uint8_t* msg, size_t len){
    REQUIRES(dut != nullptr);
    REQUIRES(msg != nullptr);
    REQUIRES(len > 0);
    REQUIRES(dut->rst_n == 1);
    //
    
    for (size_t i = 0; i < len; i++){
        push_byte(dut, msg[i]);
    }
}

static int wait_for_msg(Vitch_parser *dut, int max_cycles = 100){
    REQUIRES(dut != nullptr);
    REQUIRES(dut->rst_n == 1);
    REQUIRES(max_cycles > 0);
    //
    
    for (int i = 0; i < max_cycles; i++){
        if (dut->m_axis_tvalid){
            return i;
        }
        dut->s_axis_tvalid = 0;
        tick(dut);
    }
    return -1;
}

// enum values (matches msg_pkg)
static constexpr uint8_t MSG_NONE = 0;
static constexpr uint8_t MSG_ADD  = 1;
static constexpr uint8_t MSG_EXC  = 2;
static constexpr uint8_t MSG_DEL  = 3;
static constexpr uint8_t MSG_CXL  = 4;
static constexpr uint8_t MSG_RPL  = 5;
static constexpr uint8_t MSG_ACT  = 6;
static constexpr uint8_t MSG_OPH  = 7;

static void check(uint64_t actual, uint64_t expected, const char* name){
    REQUIRES(name != nullptr);
    //
    
    if (actual != expected){
        std::printf("FAIL %-14s got: 0x%llx, expected: 0x%llx\n",
                    name, (unsigned long long)actual, (unsigned long long)expected);
        failures++;
    }
}

static void test_add_order(Vitch_parser *dut){
    REQUIRES(dut != nullptr);
    //
    
    std::printf("TESTING: Add Order (A)\n");
    reset(dut);

    OrderAdd add;
    add.stock_locate  = 1;
    add.tracking_num  = 1;
    add.timestamp = 1000;
    add.order_ref_num = 100;
    add.is_buy = true;
    add.shares = 500;
    add.stock = "AAPL";
    add.price = 1500000; // $150.0000

    uint8_t msg[ORDER_ADD_LEN];
    build_order_add(msg, add);
    send_msg(dut, msg, ORDER_ADD_LEN);

    int waited = wait_for_msg(dut);
    if (waited < 0){
        std::printf("FAILED (no message emitted within timeout period)");
        failures++;
        return;
    }

    check(get_msg_type(dut), MSG_ADD, "msg_type");
    check(get_is_buy(dut), add.is_buy, "is_buy");
    check(get_locate(dut), add.stock_locate, "stock_locate");
    check(get_timestamp(dut), add.timestamp, "timestamp");
    check(get_order_ref(dut), add.order_ref_num, "order_ref_num");
    check(get_shares(dut), add.shares, "shares");
    check(get_stock(dut), ticker_to_u64(add.stock), "stock");
    check(get_price(dut), add.price, "price");
}

